            routerAddr,
            abi.encodeWithSignature("factory()"),
            abi.encode(factoryAddr)
        );
        vm.mockCall(
            factoryAddr,
            abi.encodeWithSignature("createPair(address,address)"),
            abi.encode(pairAddr)
        );

        // Deploy token contract
        vm.prank(owner);
        token = new GMTdoge();
    }

    function testDistributorSettingsValidation() public {
        // Initial state
        uint256 beforeDistributorGas = token.distributorGas();
        console2.log("--- BEFORE Setting distributorGas ---");
        console2.log("distributorGas:", beforeDistributorGas);

        console2.log("--- Valid setDistributorSettings(749999) ---");
        vm.prank(owner);
        token.setDistributorSettings(749999);

        uint256 afterValid = token.distributorGas();
        console2.log("--- AFTER Valid Setting ---");
        console2.log("distributorGas:", afterValid);
        assertEq(afterValid, 749999, "Valid set failed");

        console2.log("--- BEFORE Invalid Setting (750000) ---");
