        vm.expectRevert();
        token.setDistributorSettings(750000);

        uint256 afterInvalid = token.distributorGas();
        console2.log("--- AFTER Invalid Setting Attempt ---");
        console2.log("distributorGas:", afterInvalid);
        assertEq(afterInvalid, 749999, "Invalid set changed state");

        console2.log("Vulnerability Exists: Distributor settings validation bypass");
    }

    function testSwapBackSettingsValidation() public {
        // Query pre-trigger state
        bool swapEnabledBefore = token.swapEnabled();
        uint256 swapThresholdBefore = token.swapThreshold();
        console2.log("--- BEFORE setSwapBackSettings ---");
        console2.log("swapEnabled:", swapEnabledBefore);
