        console2.log("swapEnabled:", swapEnabledAfter);
        console2.log("swapThreshold:", swapThresholdAfter);

        assertTrue(swapEnabledAfter, "swapEnabled not set");
        assertEq(swapThresholdAfter, type(uint256).max, "swapThreshold not max");

        console2.log("Vulnerability Exists: SwapBack settings accept unsafe thresholds");
    }

    function testAutoBuybackSettingsValidation() public {
        // Pre-state queries
        bool enabledBefore = token.autoBuybackEnabled();
        uint256 capBefore = token.autoBuybackCap();
        uint256 amountBefore = token.autoBuybackAmount();
        uint256 blockPeriodBefore = token.autoBuybackBlockPeriod();
        console2.log("--- BEFORE setAutoBuybackSettings ---");
        console2.log("autoBuybackEnabled:", enabledBefore);
        console2.log("autoBuybackCap:", capBefore);
        console2.log("autoBuybackAmount:", amountBefore);
        console2.log("autoBuybackBlockPeriod:", blockPeriodBefore);

        console2.log("--- Trigger setAutoBuybackSettings(max) ---");
        vm.prank(owner);
        token.setAutoBuybackSettings(
            true, 
            type(uint256).max,
            type(uint256).max,
            type(uint256).max,
            true
        );

        // Post-state checks
        console2.log("--- AFTER setAutoBuybackSettings ---");
        bool enabledAfter = token.autoBuybackEnabled();
        uint256 capAfter = token.autoBuybackCap();
        uint256 amountAfter = token.autoBuybackAmount();
        uint256 blockPeriodAfter = token.autoBuybackBlockPeriod();
        console2.log("autoBuybackEnabled:", enabledAfter);
        console2.log("autoBuybackCap:", capAfter);
        console2.log("autoBuybackAmount:", amountAfter);
        console2.log("autoBuybackBlockPeriod:", blockPeriodAfter);

        assertTrue(enabledAfter, "autoBuybackEnabled not set");
