        assertEq(blockPeriodAfter, type(uint256).max, "autoBuybackBlockPeriod not max");

        console2.log("Vulnerability Exists: AutoBuyback settings accept unsafe values");
    }

    function testDistributionCriteriaValidation() public {
        // Confirm distributor contract access
