        uint256 amountBefore = token.autoBuybackAmount();
        uint256 blockPeriodBefore = token.autoBuybackBlockPeriod();
        console.log("--- BEFORE setAutoBuybackSettings ---");
        console.log("autoBuybackEnabled:", enabledBefore);
        console.log("autoBuybackCap:", capBefore);
        console.log("autoBuybackAmount:", amountBefore);
        console.log("autoBuybackBlockPeriod:", blockPeriodBefore);

